-- Migration 0036_flag_change_request: generated by drizzle-kit (table, keys, checks, index), grants hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #311)
-- Two-person enable of legal-gated feature flags from the staff console (#311, part of #27):
--   * flag_change_request: global (GLOBAL_TABLES), no RLS, staff-only like feature_flag. A row is a
--     staff request to enable a legal-gated flag (globally, or for the workspace in workspace_id)
--     with the requester's legal_ack_note, waiting for a second, different admin to approve or
--     reject it (`@causedeck/flags` requestLegalEnable / approveLegalEnable).
--   * At most one pending request per (key, workspace) target (partial unique index); the decider
--     is never the requester (CHECK); a decided row carries decided_at (CHECK).
--   * requested_by / decided_by are ON DELETE SET NULL (account deletion, #303); the workspace
--     cascades with its organization.
--   * The app role may read, insert and update rows, never delete them (decisions stay on record);
--     the clerk role gets nothing.
-- A new table only: nothing existing is altered or dropped.
CREATE TABLE "flag_change_request" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"key" text NOT NULL,
	"workspace_id" uuid,
	"legal_ack_note" text NOT NULL,
	"status" text DEFAULT 'pending' NOT NULL,
	"requested_by" uuid,
	"requested_at" timestamp with time zone DEFAULT now() NOT NULL,
	"decided_by" uuid,
	"decided_at" timestamp with time zone,
	CONSTRAINT "flag_change_request_status_chk" CHECK ("flag_change_request"."status" in ('pending', 'approved', 'rejected')),
	CONSTRAINT "flag_change_request_decided_chk" CHECK ("flag_change_request"."status" = 'pending' or "flag_change_request"."decided_at" is not null),
	CONSTRAINT "flag_change_request_not_self_chk" CHECK ("flag_change_request"."decided_by" is null or "flag_change_request"."requested_by" is null or "flag_change_request"."decided_by" <> "flag_change_request"."requested_by")
);
